import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void triu_matmul_kernel(
    int M, int N, int K,
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ C)
{
    constexpr int TILE_M = 128;
    constexpr int TILE_N = 128;
    constexpr int TILE_K = 8;

    int block_row = blockIdx.x; // tiles along M
    int block_col = blockIdx.y; // tiles along N

    // Entire tile is strictly below the diagonal -> output stays zero.
    if (block_row > block_col) return;

    int row0 = block_row * TILE_M;
    int col0 = block_col * TILE_N;

    // A: row-major (M,K)
    Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
    // B viewed as (N,K): mB(n,k) == B_true(k,n). B_true is row-major (K,N), stride (N,1).
    Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));
    // C: row-major (M,N)
    Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));

    auto cta_tiler = make_shape(Int<TILE_M>{}, Int<TILE_N>{}, Int<TILE_K>{});
    auto cta_coord = make_coord(block_row, block_col, _);

    Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{}); // (TILE_M, TILE_K, kt)
    Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{}); // (TILE_N, TILE_K, kt)
    Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{}); // (TILE_M, TILE_N)

    __shared__ T smemA0[TILE_M * TILE_K];
    __shared__ T smemA1[TILE_M * TILE_K];
    __shared__ T smemB0[TILE_N * TILE_K];
    __shared__ T smemB1[TILE_N * TILE_K];
    Tensor sA0 = make_tensor(make_smem_ptr(smemA0), make_shape(Int<TILE_M>{}, Int<TILE_K>{}));
    Tensor sA1 = make_tensor(make_smem_ptr(smemA1), make_shape(Int<TILE_M>{}, Int<TILE_K>{}));
    Tensor sB0 = make_tensor(make_smem_ptr(smemB0), make_shape(Int<TILE_N>{}, Int<TILE_K>{}));
    Tensor sB1 = make_tensor(make_smem_ptr(smemB1), make_shape(Int<TILE_N>{}, Int<TILE_K>{}));
    auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
    auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
    auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
    using CopyAtomA = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<T>, T>;
    using CopyAtomB = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<T>, T>;
    auto val_layout = make_layout(make_shape(Int<1>{}, Int<1>{}));
    auto tiled_copy_a = make_tiled_copy(CopyAtomA{}, tA, val_layout);
    auto tiled_copy_b = make_tiled_copy(CopyAtomB{}, tB, val_layout);
    auto thr_copy_a = tiled_copy_a.get_thread_slice(threadIdx.x);
    auto thr_copy_b = tiled_copy_b.get_thread_slice(threadIdx.x);
    Tensor tAgA = thr_copy_a.partition_S(gA);
    Tensor tAsA0 = thr_copy_a.partition_D(sA0);
    Tensor tAsA1 = thr_copy_a.partition_D(sA1);
    Tensor tBgB = thr_copy_b.partition_S(gB);
    Tensor tBsB0 = thr_copy_b.partition_D(sB0);
    Tensor tBsB1 = thr_copy_b.partition_D(sB1);
    Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
    Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
    Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X, _1>{});
    Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X, _1>{});
    Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});
    Tensor tCrC = make_tensor_like(tCgC);
    clear(tCrC);
    // Exploit triangular structure: only k in [row0, col0+TILE_N) can contribute
    // (A is upper-triangular: A(m,k)=0 for k<m ; B is upper-triangular: B(k,n)=0 for k>n)
    int kt_lo = row0 / TILE_K;
    int kt_hi_bound = col0 + TILE_N;
    if (kt_hi_bound > K) kt_hi_bound = K;
    int kt_hi = (kt_hi_bound + TILE_K - 1) / TILE_K;
    // Double-buffered (2-stage) pipeline using cp.async to overlap global loads
    // with compute: prefetch the next K-tile into the alternate shared-memory
    // buffer while the GEMM for the current tile is being computed.
    int total_stages = kt_hi - kt_lo;
    if (total_stages > 0) {
        // Prologue: prefetch first tile into buffer 0
        copy(tiled_copy_a, tAgA(_, _, _, kt_lo), tAsA0);
        copy(tiled_copy_b, tBgB(_, _, _, kt_lo), tBsB0);
        cp_async_fence();
        for (int idx = 0; idx < total_stages; ++idx) {
            int kt = kt_lo + idx;
            bool cur_is_0 = ((idx & 1) == 0);
            bool has_next = (idx + 1) < total_stages;
            if (has_next) {
                int kt_next = kt + 1;
                if (cur_is_0) {
                    copy(tiled_copy_a, tAgA(_, _, _, kt_next), tAsA1);
                    copy(tiled_copy_b, tBgB(_, _, _, kt_next), tBsB1);
                } else {
                    copy(tiled_copy_a, tAgA(_, _, _, kt_next), tAsA0);
                    copy(tiled_copy_b, tBgB(_, _, _, kt_next), tBsB0);
                }
                cp_async_fence();
                cp_async_wait<1>();
            } else {
                cp_async_wait<0>();
            }
            __syncthreads();
            if (cur_is_0) {
                gemm(tCsA0, tCsB0, tCrC);
            } else {
                gemm(tCsA1, tCsB1, tCrC);
            }
            __syncthreads();
        }
    }

    // Epilogue: write result, masking the diagonal tile to upper-triangular part.
    int m_thread = threadIdx.x % 16;
    int n_thread = threadIdx.x / 16;

    bool is_diag_block = (block_row == block_col);

    #pragma unroll
    for (int m = 0; m < 8; ++m) {
        int row = row0 + m_thread + m * 16;
        if (row >= M) continue;
        #pragma unroll
        for (int n = 0; n < 8; ++n) {
            int col = col0 + n_thread + n * 16;
            if (col >= N) continue;
            T val = tCrC(m, n);
            if (is_diag_block && row > col) {
                val = T(0);
            }
            mC(row, col) = val;
        }
    }
}

torch::Tensor triu_matmul_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A, B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A, B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Only float32 supported");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");

    int M = (int)A.size(0);
    int K = (int)A.size(1);
    int N = (int)B.size(1);

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C = torch::zeros({M, N}, A.options());

    constexpr int TILE_M = 128;
    constexpr int TILE_N = 128;

    dim3 block(256);
    dim3 grid((unsigned)((M + TILE_M - 1) / TILE_M),
              (unsigned)((N + TILE_N - 1) / TILE_N));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    triu_matmul_kernel<float><<<grid, block, 0, stream>>>(
        M, N, K,
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>()
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "triu_matmul_kernel launch failed: ", cudaGetErrorString(err));

    return C;
}
"""

cute_triu_matmul = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes C = triu(A @ B) for upper triangular NxN matrices A, B using a
    single fused CUTE tiled-GEMM kernel that exploits the triangular sparsity
    structure (skips fully below-diagonal output tiles and restricts the K
    reduction range per tile).
    """
    def __init__(self):
        super().__init__()
        self._ext = cute_triu_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.triu_matmul_forward(A.contiguous(), B.contiguous())

